D={y:{g:[float(x) for x in v.split(':')] for g,v in d.items()} for y,d in raw.items()}
json.dump(D,open('ed_data.json','w'))
P=json.load(open('../data/bls_gvf_parameters.json'))['rows']
N={'2019':259000e3,'2022':263000e3,'2025':272000e3,'2026':272500e3}
def favg(r,m=8): return r['f_q']+(m-3)/9*(r['f_y']-r['f_q'])
def fchg(r): return favg(r)*r['f_cy']/r['f_y']
def sel(r,x,n): return math.sqrt(max((r['a']+r['b']*n)*(x-x*x/n),0))
r27=P['unemployed_27wk_level']; ru=P['unemployed_total']; rl=P['labor_force_level']
def line(g):
    o=[]
    for y in ['2019','2022','2025','2026']:
        LF,E,U,L,n=D[y][g]; o.append((y,round(E),round(100*U/LF,2),round(100*L/LF,2),round(100*L/U,1),int(n)))
    LF1,E1,U1,L1,_=D['2026'][g]; LF0,E0,U0,L0,_=D['2025'][g]
    mL=1.645*fchg(r27)*sel(r27,(L1+L0)/2*1e3,N['2026'])/((LF1+LF0)/2*1e3)*100
    # vs 2022 independent
    LF2,E2,U2,L2,_=D['2022'][g]
    mL22=1.645*math.sqrt((favg(r27)*sel(r27,L1*1e3,N['2026'])/(LF1*1e3))**2+(favg(r27)*sel(r27,L2*1e3,N['2022'])/(LF2*1e3))**2)*100
    mE22=1.645*math.sqrt((favg(rl)*sel(rl,E1*1e3,N['2026']))**2+(favg(rl)*sel(rl,E2*1e3,N['2022']))**2)/1e3
    print(f"{g:10}",o, f"| LTUrate chg vs25 {100*L1/LF1-100*L0/LF0:+.2f} ±{mL:.2f} | vs22 {100*L1/LF1-100*L2/LF2:+.2f} ±{mL22:.2f} | emp vs22 {E1-E2:+.0f}K ±{mE22:.0f} ({100*(E1/E2-1):+.1f}%) | emp vs19 {100*(E1/D['2019'][g][1]-1):+.1f}%")
for g in ['all','e_lt','bap','e_ba','e_ma','e_pd','wc_lt','wc_ba','wc_ma','wc_pd','bap_x0','bap_x5','bap_x15','bap_x25','wcbap_x0','wcbap_x5','wcbap_x15','wcbap_x25']: line(g)
